16	#ifndef CANN_CUSTOM_OPS_GELU_DAG_H
17	#define CANN_CUSTOM_OPS_GELU_DAG_H
18	
19	#include "atvoss/util/dag.h"
20	#include "atvoss/util/vec.h"
21	#include "atvoss/util/placeholder.h"
22	
23	namespace GeluOp {
24	using namespace Ops::Base;
25	const float NEG_SQRT_EIGHT_OVER_PI = -1.595769121 * 0.044715;
26	const float TANH_APPROX_FACTOR = 1 / 0.044715;
27	const int CAST_MODE_NONE = 0;
28	const int CAST_MODE_RINT = 1;
29	// tbe realization: x / (1 + e^(-1.5957691(x + 0.044715 x * x * x)))
30	// current realization: x / (1 + e^(-1.5957691*0.044715(x/0.044715 + x^3)))
31	namespace GeluDag1 {
32	template <class T>
33	struct GeluCustom : public Vec::ElemwiseUnaryOP<T, T> {
34	    __aicore__ inline GeluCustom(LocalTensor<T>& dst, LocalTensor<T>& src, uint32_t count)
35	    {
36	#ifdef __CCE_AICORE__
37	        uint32_t dtypeSize = sizeof(T);
38	        uint32_t vl = VECTOR_REG_WIDTH / dtypeSize;
39	        uint16_t loopNum = CeilDivision(count, vl);
40	        uint32_t vlSize = vl;
41	        __ubuf__ T* srcAddr = (__ubuf__ T*)src.GetPhyAddr();
42	        __ubuf__ T* dstAddr = (__ubuf__ T*)dst.GetPhyAddr();
43	
44	        MicroAPI::RegTensor<T, MicroAPI::RegTraitNumOne> vregInput;
45	        MicroAPI::RegTensor<T, MicroAPI::RegTraitNumOne> vregInputSqr;
46	        MicroAPI::RegTensor<T, MicroAPI::RegTraitNumOne> vregInputCub;
47	        MicroAPI::RegTensor<T, MicroAPI::RegTraitNumOne> vregOutput;
48	        MicroAPI::MaskReg mask;
49	        if constexpr (std::is_same_v<T, float>) {
50	            __VEC_SCOPE__
51	            {
52	                for (uint16_t loopIdx = 0; loopIdx < loopNum; loopIdx++) {
53	                    mask = MicroAPI::UpdateMask<T, MicroAPI::RegTraitNumOne>(count);
54	                    // OpCopyIn
55	                    MicroAPI::DataCopy(vregInput, (__ubuf__ T*)(srcAddr + loopIdx * vlSize));
56	                    MicroAPI::Mul(vregInputSqr, vregInput, vregInput, mask);
57	                    MicroAPI::Mul(vregInputCub, vregInputSqr, vregInput, mask);
58	                    MicroAPI::Axpy(vregInputCub, vregInput, TANH_APPROX_FACTOR, mask);
59	                    MicroAPI::Muls(vregInputCub, vregInputCub, NEG_SQRT_EIGHT_OVER_PI, mask);
60	                    MicroAPI::Exp(vregInputCub, vregInputCub, mask);
61	                    MicroAPI::Adds(vregInputCub, vregInputCub, (float)1.0, mask);
62	                    MicroAPI::Div(vregOutput, vregInput, vregInputCub, mask);
63	
64	                    // OpCopyOut
65	                    MicroAPI::DataCopy((__ubuf__ T*)(dstAddr + loopIdx * vlSize), vregOutput, mask);
66	                }
67	            }
68	        }
69	#endif
70	    }
71	};
72	} // namespace GeluDag1
73	
74	template <typename U, typename T = float>
75	struct GeluDAG {
76	    using OpCopyIn0 = Bind<Vec::CopyIn<U>, Placeholder::In0<U>>;
77	    using OpCopyIn0Cast = Bind<Vec::Cast<T, U, CAST_MODE_NONE>, OpCopyIn0>;
78	
79	    using OpLogResult = Bind<GeluDag1::GeluCustom<T>, OpCopyIn0Cast>;
80	    using OpResultCast = Bind<Vec::Cast<U, T, CAST_MODE_RINT>, OpLogResult>;
81	    using OpCopyOut = Bind<Vec::CopyOut<U>, Placeholder::Out0<U>, OpResultCast>;
82	
83	    using Outputs = Elems<OpCopyOut>;
84	    using MemCfg = MemOptCfg<MemLevel::LEVEL_2>;
85	    using OpDag = DAGSch<Outputs, void, MemCfg>;
86	};
87	} // namespace GeluOp
88	#endif // CANN_CUSTOM_OPS_GELU_DAG_H

