19	#include <iostream>
20	
21	namespace optiling {
22	const size_t ASCEND_WORKSPACE = 16777216; // 16M
23	const gert::Shape g_vec_1_shape = {1};
24	
25	ge::graphStatus GeluTiling::CalcInputDtype()
26	{
27	    OP_LOGD(tilingContext->GetNodeName(), "GeluTiling CalcInputDtype enter.");
28	    auto inputDesc = tilingContext->GetInputDesc(0);
29	    OP_CHECK_NULL_WITH_CONTEXT(tilingContext, inputDesc);
30	    this->inputDtype = inputDesc->GetDataType();
31	    OP_CHECK_IF(
32	        this->inputDtype != ge::DT_FLOAT16 && this->inputDtype != ge::DT_BF16 && this->inputDtype != ge::DT_FLOAT,
33	        OP_LOGE_FOR_INVALID_DTYPE_WITH_REASON(
34	            tilingContext->GetNodeName(), "x",
35	            ge::TypeUtils::DataTypeToSerialString(static_cast<ge::DataType>(this->inputDtype)),
36	            "The dtype of x must be DT_FLOAT16, DT_BF16, or DT_FLOAT"),
37	        return ge::GRAPH_FAILED);
38	    return ge::GRAPH_SUCCESS;
39	}
40	
41	static inline const gert::Shape& EnsureNotScalar(const gert::Shape& in_shape)
42	{
43	    if (in_shape.IsScalar()) {
44	        return g_vec_1_shape;
45	    }
46	    return in_shape;
47	}
48	
49	ge::graphStatus GeluTiling::CheckShape()
50	{
51	    OP_LOGD(tilingContext->GetNodeName(), "GeluTiling CheckShape enter.");
52	    auto inputStorageShape = tilingContext->GetInputShape(0);
53	    OP_CHECK_NULL_WITH_CONTEXT(tilingContext, inputStorageShape);
54	    const gert::Shape& inputYShape = EnsureNotScalar(inputStorageShape->GetStorageShape());
55	
56	    auto outputStorageShape = tilingContext->GetOutputShape(0);
57	    OP_CHECK_NULL_WITH_CONTEXT(tilingContext, outputStorageShape);
58	    const gert::Shape& outputZShape = EnsureNotScalar(outputStorageShape->GetStorageShape());
59	
60	    OP_CHECK_IF(inputYShape != outputZShape,
61	                OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(
62	                    tilingContext->GetNodeName(), "x, y",
63	                    Ops::Base::ToString(inputYShape) + ", " + Ops::Base::ToString(outputZShape),
64	                    "The shapes of x and y must be the same"),
65	                return ge::GRAPH_FAILED);
66	    return ge::GRAPH_SUCCESS;
67	}
68	
69	ge::graphStatus GeluTiling::CalcOutputDtype()
70	{
71	    OP_LOGD(tilingContext->GetNodeName(), "GeluTiling CalcOutputDtype enter.");
72	    auto outputDesc = tilingContext->GetOutputDesc(0);
73	    OP_CHECK_NULL_WITH_CONTEXT(tilingContext, outputDesc);
74	    this->outputDtype = outputDesc->GetDataType();
75	    OP_CHECK_IF(this->outputDtype != this->inputDtype,
76	                OP_LOGE_FOR_INVALID_DTYPES_WITH_REASON(
77	                    tilingContext->GetNodeName(), "x, y",
78	                    ge::TypeUtils::DataTypeToSerialString(static_cast<ge::DataType>(this->inputDtype)) + ", " +
79	                        ge::TypeUtils::DataTypeToSerialString(static_cast<ge::DataType>(this->outputDtype)),
80	                    "The dtypes of x and y must be the same"),
81	                return ge::GRAPH_FAILED);
82	    return ge::GRAPH_SUCCESS;
83	}
84	
85	ge::graphStatus GeluTiling::RunTiling()
86	{
87	    auto tiling = tilingContext->GetTilingData<Ops::Base::EleBaseTilingData16B>();
88	
89	    OP_LOGD(tilingContext->GetNodeName(), "GeluTiling RunTiling enter.");
90	    ElewiseBaseTiling elewiseBaseTiling(tilingContext);
91	    OP_CHECK_IF(CalcInputDtype() == ge::GRAPH_FAILED, OP_LOGE(tilingContext, "get input dtype failed"),
92	                return ge::GRAPH_FAILED);
93	    OP_CHECK_IF(CalcOutputDtype() == ge::GRAPH_FAILED, OP_LOGE(tilingContext, "get output dtype failed"),
94	                return ge::GRAPH_FAILED);
95	    OP_CHECK_IF(CheckShape() == ge::GRAPH_FAILED, OP_LOGE(tilingContext, "check shape failed"),
96	                return ge::GRAPH_FAILED);
97	
98	    ge::graphStatus baseTilingResult = ge::GRAPH_FAILED;
99	    if (this->outputDtype == ge::DT_FLOAT16) {
100	        dType = TPL_FP16;
101	        baseTilingResult = elewiseBaseTiling.DoTiling<GeluOp::GeluDAG<half>::OpDag>(*tiling);
102	    } else if (this->outputDtype == ge::DT_BF16) {
103	        dType = TPL_BF16;
104	        baseTilingResult = elewiseBaseTiling.DoTiling<GeluOp::GeluDAG<bfloat16_t>::OpDag>(*tiling);
105	    } else if (this->outputDtype == ge::DT_FLOAT) {
106	        dType = TPL_FP32;
107	        baseTilingResult = elewiseBaseTiling.DoTiling<GeluOp::GeluDAG<float>::OpDag>(*tiling);
108	    } else {
109	        OP_LOGE_FOR_INVALID_DTYPE_WITH_REASON(
110	            tilingContext->GetNodeName(), "y",
111	            ge::TypeUtils::DataTypeToSerialString(static_cast<ge::DataType>(this->outputDtype)),
112	            "The dtype of y must be DT_FLOAT16, DT_BF16, or DT_FLOAT");
113	        return ge::GRAPH_FAILED;
114	    }
115	    OP_CHECK_IF(baseTilingResult == ge::GRAPH_FAILED, OP_LOGE(tilingContext, "elewiseBaseTiling failed"),
116	                return ge::GRAPH_FAILED);
117	
118	    size_t* currentWorkspace = tilingContext->GetWorkspaceSizes(1);
119	    OP_CHECK_NULL_WITH_CONTEXT(tilingContext, currentWorkspace);
120	    currentWorkspace[0] = ASCEND_WORKSPACE;
121	
122	    const uint64_t tilingKey = GET_TPL_TILING_KEY(1, dType);
123	    OP_LOGD(tilingContext->GetNodeName(), "[TilingData] : tilingKey=%lu", tilingKey);
124	    tilingContext->SetTilingKey(tilingKey);
125	    tilingContext->SetBlockDim(elewiseBaseTiling.GetBlockDim());
126	    return ge::GRAPH_SUCCESS;
127	}
128	
129	static ge::graphStatus Tiling4Gelu(gert::TilingContext* tilingContextGen)
130	{
131	    OP_LOGD(tilingContextGen->GetNodeName(), "Tiling4Gelu rt2.0 is running.");
132	    auto compileInfo = tilingContextGen->GetCompileInfo<GeluCompileInfo>();
133	    OP_CHECK_NULL_WITH_CONTEXT(tilingContextGen, compileInfo);
134	
135	    GeluTiling baseOpTiling(tilingContextGen);
136	    return baseOpTiling.RunTiling();
137	}
138	
139	ge::graphStatus TilingPrepareForGelu(gert::TilingParseContext* context)
140	{
141	    auto compileInfoPtr = context->GetCompiledInfo<GeluCompileInfo>();
142	    OP_CHECK_NULL_WITH_CONTEXT(context, compileInfoPtr);
143	    fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
144	    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfoPtr);
145	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
146	    compileInfoPtr->coreNum = ascendcPlatform.GetCoreNumAiv();
147	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
148	    return ge::GRAPH_SUCCESS;
149	}
150	
151	IMPL_OP_OPTILING(Gelu).Tiling(Tiling4Gelu).TilingParse<GeluCompileInfo>(TilingPrepareForGelu);
152	} // namespace optiling

